def transform(grid):
    h, w = len(grid), len(grid[0])
    rh, rw = h // 3, w // 3
    out = [[0]*rw for _ in range(rh)]
    for r in range(rh):
        for c in range(rw):
            found = None
            for r2 in range(3*r, 3*r+3):
                for c2 in range(3*c, 3*c+3):
                    if grid[r2][c2] not in (0, 5):
                        found = grid[r2][c2]
                        break
            if found is not None:
                out[r][c] = found
    return out

